// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address ownerCandidate, address newImpl) public {
        vm.assume(ownerCandidate != address(0));
        vm.assume(newImpl != address(0));
        c.initialize();

        c.transferOwnership(ownerCandidate);

        vm.prank(ownerCandidate);
        bool ok;
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.roundImplementation() == newImpl);
        } else {
            assertTrue(c.roundImplementation() != newImpl);
        }
    }
}
